// =============================================================================
// LLM Client — Claude API wrapper using Paperclip SDK
// =============================================================================
import type { PluginHttpClient } from "@paperclipai/plugin-sdk";
import type { LLMModel, LLMPurpose, LLMUsage } from "./types.js";

// Model ID mapping
const MODEL_IDS: Record<string, string> = {
  opus: "claude-opus-4-20250514",
  sonnet: "claude-sonnet-4-20250514",
  haiku: "claude-haiku-4-5-20251001",
};

// Cost per million tokens (USD) — approximate
const COST_PER_M_TOKENS: Record<string, { input: number; output: number }> = {
  opus: { input: 15, output: 75 },
  sonnet: { input: 3, output: 15 },
  haiku: { input: 0.8, output: 4 },
};

export interface LLMRequest {
  model: LLMModel;
  purpose: LLMPurpose;
  system?: string;
  messages: Array<{ role: "user" | "assistant"; content: string }>;
  maxTokens?: number;
  temperature?: number;
}

export interface LLMResponse {
  content: string;
  usage: {
    inputTokens: number;
    outputTokens: number;
  };
  model: string;
  stopReason: string;
}

export interface LLMClientDeps {
  http: PluginHttpClient;
  apiKey: string;
}

const API_URL = "https://api.anthropic.com/v1/messages";

export async function callLLM(
  deps: LLMClientDeps,
  request: LLMRequest
): Promise<{ response: LLMResponse; usageRecord: Omit<LLMUsage, "id" | "projectId" | "timestamp"> }> {
  const apiKey = deps.apiKey;
  if (!apiKey) throw new Error("Anthropic API key not configured. Go to project detail → gear icon → enter your key.");
  const modelId = MODEL_IDS[request.model];
  if (!modelId) throw new Error(`Unknown model: ${request.model}`);

  const body: Record<string, unknown> = {
    model: modelId,
    max_tokens: request.maxTokens || 4096,
    messages: request.messages,
  };
  if (request.system) body.system = request.system;
  if (request.temperature !== undefined) body.temperature = request.temperature;

  const res = await deps.http.fetch(API_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": apiKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Claude API ${res.status}: ${errText}`);
  }

  const data = await res.json() as {
    content: Array<{ type: string; text?: string }>;
    usage: { input_tokens: number; output_tokens: number };
    model: string;
    stop_reason: string;
  };

  const textContent = data.content
    .filter((c) => c.type === "text" && c.text)
    .map((c) => c.text!)
    .join("");

  const inputTokens = data.usage.input_tokens;
  const outputTokens = data.usage.output_tokens;
  const costs = COST_PER_M_TOKENS[request.model] || { input: 0, output: 0 };
  const estimatedCostUsd =
    (inputTokens / 1_000_000) * costs.input +
    (outputTokens / 1_000_000) * costs.output;

  return {
    response: {
      content: textContent,
      usage: { inputTokens, outputTokens },
      model: data.model,
      stopReason: data.stop_reason,
    },
    usageRecord: {
      model: request.model,
      purpose: request.purpose,
      inputTokens,
      outputTokens,
      estimatedCostUsd,
    },
  };
}

