];

// ---------------------------------------------------------------------------
// Sidebar component
// ---------------------------------------------------------------------------

function PhoebeSidebar() {
  return (
    <nav
      aria-label="Phoebe navigation"
      className="w-48 shrink-0 border-r border-zinc-800 bg-zinc-950 py-6 px-3"
    >
      <p className="text-xs uppercase tracking-widest text-zinc-500 px-3 mb-3">
        Phoebe
